package com.tekwatt.admin.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="administrators",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","email"}))public class Administrator{@Id private UUID id;@Column(nullable=false)private UUID tenantId;private UUID authUserId;@Column(nullable=false,length=120)private String name;@Column(nullable=false,length=190)private String email;@Column(length=32)private String phone;@Column(nullable=false,length=60)private String roleName;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected Administrator(){}public Administrator(UUID t,UUID auth,String n,String e,String p,String r){id=UUID.randomUUID();tenantId=t;authUserId=auth;createdAt=Instant.now();update(n,e,p,r,"ACTIVE");}public void update(String n,String e,String p,String r,String s){name=n;email=e;phone=p;roleName=r;status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getAuthUserId(){return authUserId;}public String getName(){return name;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getRoleName(){return roleName;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
